/* Restores a saved non-visual project into its matching workspace without
   creating a second project or discarding the original conversation. */
(() => {
  const projectId = new URLSearchParams(location.search).get('project');
  const workspace = document.body.dataset.workspace;
  if (!projectId || !workspace || workspace === 'visual') return;
  const $ = selector => document.querySelector(selector);
  const request = async (path, options = {}) => { const response = await fetch(path, { credentials: 'same-origin', ...options }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.error || 'Request failed'); return body; };
  const language = () => document.documentElement.lang === 'en' ? 'en' : 'zh';
  const words = () => language() === 'en' ? { restored:'Your project is ready. Choose how you would like to continue.', chat:'Continue discussing', make:'Continue making', task:'Add a detail or ask a question about this project…', saved:'Project saved.' } : { restored:'项目已恢复。请选择下一步。', chat:'继续聊这个项目', make:'继续制作', task:'补充需求或继续讨论这个项目…', saved:'项目已保存。' };
  let project, messages=[];
  const metaFor = items => (items || []).find(item => item?.type === 'project_meta');
  const projectConversation = () => [{ type:'project_meta', workspace, intent:workspace, task:$('#taskInput').value.trim() || messages.at(-1)?.question || '' }, ...messages];
  function render() { const history=$('#workspaceHistory'); history.replaceChildren(); messages.forEach(message=>{const card=document.createElement('article'),q=document.createElement('strong'),a=document.createElement('p');q.textContent=message.question||'';a.textContent=message.answer||'';card.append(q,a);history.append(card);});$('#workspaceResults').hidden=!messages.length; }
  function actions() { const panel=document.createElement('div'),note=document.createElement('small'),chat=document.createElement('button'),make=document.createElement('button'); panel.className='visual-project-choices';note.textContent=words().restored;chat.type=make.type='button';chat.textContent=words().chat;make.textContent=words().make;chat.onclick=()=>{$('#taskInput').placeholder=words().task;$('#taskInput').focus();};make.onclick=()=>{$('#taskInput').scrollIntoView({behavior:'smooth',block:'center'});$('#taskInput').focus({preventScroll:true});};panel.append(note,chat,make);$('#workspaceForm').before(panel); }
  async function update() { await request('/api/member/projects',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:project.id,locale:language(),conversation:projectConversation()})}); }
  async function restore() { try { project=await request('/api/member/projects?id='+encodeURIComponent(projectId)); const meta=metaFor(project.conversation); if (!meta || meta.workspace!==workspace) return; messages=(project.conversation||[]).filter(item=>item?.type!=='project_meta'&&item?.type!=='workspace_state'); $('#taskInput').value=meta.task||messages.at(-1)?.question||''; render(); actions(); const oldForm=$('#workspaceForm'),form=oldForm.cloneNode(true); oldForm.replaceWith(form); form.addEventListener('submit',async event=>{event.preventDefault();const input=$('#taskInput'),question=input.value.trim();if(!question)return;const status=$('#workspaceStatus');try{const response=await request('/api/recommend',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query:question,language:language(),context:messages.slice(-4),taskType:workspace})});messages.push({question,answer:response.answer||''});input.value='';await update();render();status.textContent=words().saved;}catch(error){status.textContent=error.message;}}); const save=$('#saveProject'); save?.addEventListener('click',()=>update().then(()=>{$('#workspaceStatus').textContent=words().saved;}).catch(error=>{$('#workspaceStatus').textContent=error.message;})); } catch (error) { $('#workspaceStatus').textContent=error.message; } }
  restore();
})();
